import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-establishments.json"), "utf8"),
);
const output = emitModels(contract.models);
await writeGenerated(
  root,
  "backend/internal/modules/workforce/establishment_types_generated.go",
  '// Code generated by scripts/generate-workforce-establishments.mjs; DO NOT EDIT.\npackage workforce\nimport (\n"time"\n\n"github.com/google/uuid"\n)\n' +
    output.go,
  "packages/api/src/workforce-establishment-contract.ts",
  '// Generated by scripts/generate-workforce-establishments.mjs.\nimport {z} from "zod";\n' +
    output.ts,
  "Workforce establishment",
);
